#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>

static void skip_ws(const char **p) {
    while (**p && isspace((unsigned char)**p)) (*p)++;
}

static void skip_delims(const char **p) {
    while (**p && (isspace((unsigned char)**p) || **p == ',')) (*p)++;
}

static int parse_int(const char **p) {
    skip_delims(p);
    int value = 0;
    while (**p && isdigit((unsigned char)**p)) {
        value = value * 10 + (**p - '0');
        (*p)++;
    }
    return value;
}

static int parse_int_array(const char **p, int **out) {
    skip_ws(p);
    if (**p != '[') return 0;
    (*p)++;

    int capacity = 16;
    int size = 0;
    int *arr = (int *)malloc((size_t)capacity * sizeof(int));

    skip_ws(p);
    if (**p == ']') {
        (*p)++;
        *out = arr;
        return 0;
    }

    while (**p) {
        if (size == capacity) {
            capacity *= 2;
            arr = (int *)realloc(arr, (size_t)capacity * sizeof(int));
        }

        arr[size++] = parse_int(p);
        skip_ws(p);

        if (**p == ',') {
            (*p)++;
        } else if (**p == ']') {
            (*p)++;
            break;
        }
    }

    *out = arr;
    return size;
}

static int **parse_matrix(const char **p, int *rows, int **cols) {
    skip_ws(p);
    if (**p != '[') return NULL;
    (*p)++;

    int capacity = 16;
    int count = 0;
    int **matrix = (int **)malloc((size_t)capacity * sizeof(int *));
    int *col_sizes = (int *)malloc((size_t)capacity * sizeof(int));

    skip_ws(p);
    if (**p == ']') {
        (*p)++;
        *rows = 0;
        *cols = col_sizes;
        return matrix;
    }

    while (**p) {
        if (count == capacity) {
            capacity *= 2;
            matrix = (int **)realloc(matrix, (size_t)capacity * sizeof(int *));
            col_sizes = (int *)realloc(col_sizes, (size_t)capacity * sizeof(int));
        }

        matrix[count] = NULL;
        col_sizes[count] = parse_int_array(p, &matrix[count]);
        count++;

        skip_ws(p);
        if (**p == ',') {
            (*p)++;
        } else if (**p == ']') {
            (*p)++;
            break;
        }
    }

    *rows = count;
    *cols = col_sizes;
    return matrix;
}

int **matrixBlockSum(
    int **mat, int matSize, int *matColSize, int k,
    int *returnSize, int **returnColumnSizes
) {
    int m = matSize;
    int n = matColSize[0];

    long long **prefix = (long long **)malloc((size_t)(m + 1) * sizeof(long long *));
    for (int i = 0; i <= m; ++i) {
        prefix[i] = (long long *)calloc((size_t)(n + 1), sizeof(long long));
    }

    for (int i = 0; i < m; ++i) {
        long long row_sum = 0;
        for (int j = 0; j < n; ++j) {
            row_sum += mat[i][j];
            prefix[i + 1][j + 1] = prefix[i][j + 1] + row_sum;
        }
    }

    int **answer = (int **)malloc((size_t)m * sizeof(int *));
    int *answer_cols = (int *)malloc((size_t)m * sizeof(int));

    for (int i = 0; i < m; ++i) {
        answer[i] = (int *)malloc((size_t)n * sizeof(int));
        answer_cols[i] = n;

        int r1 = i - k < 0 ? 0 : i - k;
        int r2 = i + k >= m ? m - 1 : i + k;

        for (int j = 0; j < n; ++j) {
            int c1 = j - k < 0 ? 0 : j - k;
            int c2 = j + k >= n ? n - 1 : j + k;

            long long sum =
                prefix[r2 + 1][c2 + 1]
                - prefix[r1][c2 + 1]
                - prefix[r2 + 1][c1]
                + prefix[r1][c1];

            answer[i][j] = (int)sum;
        }
    }

    for (int i = 0; i <= m; ++i) free(prefix[i]);
    free(prefix);

    *returnSize = m;
    *returnColumnSizes = answer_cols;
    return answer;
}

int main(void) {
    char line[1000000];
    if (!fgets(line, sizeof(line), stdin)) return 0;

    const char *p = line;
    skip_ws(&p);
    if (*p != '[') return 0;
    ++p;

    int rows = 0;
    int *cols = NULL;
    int **mat = parse_matrix(&p, &rows, &cols);

    int k = parse_int(&p);

    int return_size = 0;
    int *return_cols = NULL;
    int **result = matrixBlockSum(mat, rows, cols, k, &return_size, &return_cols);

    printf("[");
    for (int i = 0; i < return_size; ++i) {
        if (i) printf(",");
        printf("[");
        for (int j = 0; j < return_cols[i]; ++j) {
            if (j) printf(",");
            printf("%d", result[i][j]);
        }
        printf("]");
    }
    printf("]\n");

    for (int i = 0; i < rows; ++i) free(mat[i]);
    free(mat);
    free(cols);

    for (int i = 0; i < return_size; ++i) free(result[i]);
    free(result);
    free(return_cols);

    return 0;
}

