class Solution {
public:
    vector<vector<int>> matrixBlockSum(vector<vector<int>>& mat, int k) {
        int m = (int)mat.size();
        int n = (int)mat[0].size();
        vector<vector<int>> prefix(m + 1, vector<int>(n + 1, 0));

        for (int i = 0; i < m; ++i) {
            int rowSum = 0;
            for (int j = 0; j < n; ++j) {
                rowSum += mat[i][j];
                prefix[i + 1][j + 1] = prefix[i][j + 1] + rowSum;
            }
        }

        vector<vector<int>> answer(m, vector<int>(n, 0));
        for (int i = 0; i < m; ++i) {
            int r1 = max(0, i - k);
            int r2 = min(m - 1, i + k);
            for (int j = 0; j < n; ++j) {
                int c1 = max(0, j - k);
                int c2 = min(n - 1, j + k);
                answer[i][j] =
                    prefix[r2 + 1][c2 + 1]
                    - prefix[r1][c2 + 1]
                    - prefix[r2 + 1][c1]
                    + prefix[r1][c1];
            }
        }
        return answer;
    }
};

static vector<string> splitTopLevel(const string& s) {
    string body = s.substr(1, s.size() - 2);
    vector<string> parts;
    int depth = 0, start = 0;
    for (int i = 0; i < (int)body.size(); ++i) {
        if (body[i] == '[') ++depth;
        else if (body[i] == ']') --depth;
        else if (body[i] == ',' && depth == 0) {
            parts.push_back(body.substr(start, i - start));
            start = i + 1;
        }
    }
    parts.push_back(body.substr(start));
    return parts;
}

static vector<int> parseIntArray(const string& s) {
    vector<string> parts = splitTopLevel(s);
    vector<int> result;
    for (const string& part : parts) result.push_back(stoi(part));
    return result;
}

static vector<vector<int>> parseMatrix(const string& s) {
    vector<string> rows = splitTopLevel(s);
    vector<vector<int>> result;
    for (const string& row : rows) result.push_back(parseIntArray(row));
    return result;
}

static pair<string, string> parseArguments(string line) {
    line = line.substr(1, line.size() - 2);
    int depth = 0;
    for (int i = 0; i < (int)line.size(); ++i) {
        if (line[i] == '[') ++depth;
        else if (line[i] == ']') --depth;
        else if (line[i] == ',' && depth == 0) {
            return {line.substr(0, i), line.substr(i + 1)};
        }
    }
    throw runtime_error("Invalid input");
}

static void printMatrix(const vector<vector<int>>& matrix) {
    cout << '[';
    for (int i = 0; i < (int)matrix.size(); ++i) {
        if (i) cout << ',';
        cout << '[';
        for (int j = 0; j < (int)matrix[i].size(); ++j) {
            if (j) cout << ',';
            cout << matrix[i][j];
        }
