import java.io.*;
import java.util.*;

class Solution {
    public int[][] matrixBlockSum(int[][] mat, int k) {
        int m = mat.length;
        int n = mat[0].length;
        int[][] prefix = new int[m + 1][n + 1];

        for (int i = 0; i < m; i++) {
            int rowSum = 0;
            for (int j = 0; j < n; j++) {
                rowSum += mat[i][j];
                prefix[i + 1][j + 1] = prefix[i][j + 1] + rowSum;
            }
        }

        int[][] answer = new int[m][n];
        for (int i = 0; i < m; i++) {
            int r1 = Math.max(0, i - k);
            int r2 = Math.min(m - 1, i + k);
            for (int j = 0; j < n; j++) {
                int c1 = Math.max(0, j - k);
                int c2 = Math.min(n - 1, j + k);
                answer[i][j] =
                    prefix[r2 + 1][c2 + 1]
                    - prefix[r1][c2 + 1]
                    - prefix[r2 + 1][c1]
                    + prefix[r1][c1];
            }
        }
        return answer;
    }
}

public class Main {
    static String[] splitTopLevel(String s) {
        s = s.trim();
        if (s.equals("[]")) return new String[0];
        s = s.substring(1, s.length() - 1);
        List<String> parts = new ArrayList<>();
        int depth = 0, start = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '[') depth++;
            else if (ch == ']') depth--;
            else if (ch == ',' && depth == 0) {
                parts.add(s.substring(start, i).trim());
                start = i + 1;
            }
        }
        parts.add(s.substring(start).trim());
        return parts.toArray(new String[0]);
    }

    static int[] parseIntArray(String s) {
        String[] parts = splitTopLevel(s);
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = Integer.parseInt(parts[i].trim());
        }
        return result;
    }

    static int[][] parseMatrix(String s) {
        String[] rows = splitTopLevel(s);
        int[][] result = new int[rows.length][];
        for (int i = 0; i < rows.length; i++) {
            result[i] = parseIntArray(rows[i]);
        }
        return result;
    }

    static String[] parseArguments(String line) {
        line = line.trim();
        line = line.substring(1, line.length() - 1);
        int depth = 0;
        for (int i = 0; i < line.length(); i++) {
            char ch = line.charAt(i);
            if (ch == '[') depth++;
            else if (ch == ']') depth--;
            else if (ch == ',' && depth == 0) {
                return new String[] {
                    line.substring(0, i).trim(),
                    line.substring(i + 1).trim()
                };
            }
        }
        throw new IllegalArgumentException("Invalid input");
    }

    static String serialize(int[][] matrix) {
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < matrix.length; i++) {
            if (i > 0) sb.append(',');
            sb.append('[');
            for (int j = 0; j < matrix[i].length; j++) {
                if (j > 0) sb.append(',');
                sb.append(matrix[i][j]);
            }
            sb.append(']');
        }
        sb.append(']');
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        String[] parsed = parseArguments(line);
        int[][] mat = parseMatrix(parsed[0]);
        int k = Integer.parseInt(parsed[1]);
        System.out.println(serialize(new Solution().matrixBlockSum(mat, k)));
    }
}

