const readline = require('readline');

function matrixBlockSum(mat, k) {
    const m = mat.length;
    const n = mat[0].length;
    const prefix = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

    for (let i = 0; i < m; i++) {
        let rowSum = 0;
        for (let j = 0; j < n; j++) {
            rowSum += mat[i][j];
            prefix[i + 1][j + 1] = prefix[i][j + 1] + rowSum;
        }
    }

    const answer = Array.from({ length: m }, () => Array(n).fill(0));
    for (let i = 0; i < m; i++) {
        const r1 = Math.max(0, i - k);
        const r2 = Math.min(m - 1, i + k);
        for (let j = 0; j < n; j++) {
            const c1 = Math.max(0, j - k);
